  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 14, 10, 10, 7, 5, '{"niche_fit": "Iconic rotating curling iron with highly demonstrable results \u2014 strong hair-tutorial fit.", "ugc_evidence": "Structured ambassador and creator programs on the brand''s own site, with featuring on brand social channels as a stated perk.", "compensation": "The brand publishes only an ''up to 20%'' ceiling and a directory lists 5.6% for a network variant \u2014 conflicting/ceiling figures, so the rate is recorded null.", "contact_access": "Public application pages for creators and ambassadors on the official site.", "opportunity_availability": "Applications are public, though the creators page notes application windows (e.g., opening in September), so availability is partly seasonal.", "credibility": "Long-established, widely retailed hair tools brand with national press features."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Made by Mitchell', 'https://madebymitchell.co.uk', 'UK makeup brand founded in 2020 by makeup artist Mitchell Halliday (Mmmmitchell), known for Blursh liquid blush, Curve Case palettes and bold artistry products; it joined TikTok Shop in 2022/2023, became a cornerstone of UK TikTok beauty, and now sells into the US.', 'United Kingdom', 'published') returning id into bid;
