  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://rateful.ai/brand/made-by-mitchell', 'listing', 'affiliate_program', 'Rateful''s TikTok Shop data page confirms Made by Mitchell runs a TikTok Shop affiliate program: about 85% of its estimated $548K in TikTok Shop sales in the 30 days to Nov 6, 2026 came through affiliate creators'' videos and LIVEs, across 22,226 items at a $24.68 average price; creators with TikTok Shop affiliate access add products to their showcase and earn commission on every sale. No commission rate is published.', 'publicly_reported', now());
