  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 17, 10, 5, 8, 4, '{"niche_fit": "Artistry-led colour makeup from a creator-founder is a natural fit for beauty creators.", "ugc_evidence": "About 85% of its TikTok Shop sales are estimated to come through affiliate creators \u2014 one of the most affiliate-driven beauty brands on the platform.", "compensation": "Commission on every TikTok Shop sale is confirmed, but no rate is published in the sources fetched, so the rate is recorded null.", "contact_access": "No public partnerships email or application page was found on the pages fetched; access is via TikTok Shop.", "opportunity_availability": "Open to creators with TikTok Shop affiliate access via the showcase model, with free samples requestable in the affiliate center.", "credibility": "Founded 2020, a cornerstone UK TikTok Shop beauty brand with US expansion and national press coverage."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('YIANNA', 'https://shop.tiktok.com/us/pdp/yianna-overbust-fajas-colombianas-shapewear-tummy-control/1732088899760984856', 'Shapewear brand selling Fajas Colombianas tummy-control bodysuits and brief shapers through TikTok Shop (YIANNA INC official shop, ~1.5M units sold, seller address in California) at $38.99–$68.99 price points; no own DTC storefront was verified — yianna.com belongs to an unrelated wedding-accessories business.', 'United States', 'published') returning id into bid;
