  insert into public.brands (name, website, description, country, status) values ('Toplux Nutrition', 'https://topluxnutrition.com', 'US supplement brand (Lux Global Inc, Glendale, California) selling magnesium complexes, berberine, apple cider vinegar gummies and detox formulas. It has built its business almost entirely on TikTok Shop affiliate creators: its 8-form Magnesium Complex was the #2 best-selling product on TikTok Shop US in Q1 2026 with $9.5M in quarterly revenue, and third-party platform data attributes 99.7% of its sales to affiliates.', 'United States', 'published') returning id into bid;
