  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'TikTok Shop affiliate products — Toplux Nutrition official shop', null, 'https://shop.tiktok.com/us/pdp/magnesium-complex-by-toplux-8-essential-magnesium-forms-in-one-capsule/1729448464509734958?source=product_detail&enter_method=feed_list_recommended_category&first_entrance=product_detail&first_entrance_position=feed_list_recommended_category&first_entrance_tt_scene=seo', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.fastmoss.com/blog/top-selling-products-tiktok-shop-us-q1-2026/', 'listing', 'affiliate', 'FastMoss''s Q1 2026 TikTok Shop US top-10 (compiled from its platform sales data) ranks Toplux Magnesium Complex 8-in-1 #2 with $9,526,928 Q1 revenue, 414,503 orders and a 30% commission — the highest commission rate in the top 10.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://tokconnect.com/for/d2c-brands/', 'listing', 'affiliate', 'TokConnect''s TikTok Shop data for the 30 days to October 18, 2026 shows Toplux''s hero magnesium product paying 25% commission with 5,520 creators selling it, and Toplux Nutrition making $3.48M in 30 days of which 99.7% came through affiliates.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://shop.tiktok.com/us/pdp/magnesium-complex-by-toplux-8-essential-magnesium-forms-in-one-capsule/1729448464509734958?source=product_detail&enter_method=feed_list_recommended_category&first_entrance=product_detail&first_entrance_position=feed_list_recommended_category&first_entrance_tt_scene=seo', 'official_site', 'general', 'The Toplux Nutrition TikTok Shop product page shows an OFFICIAL SHOP with 4.1M units sold and 140.6K+ followers; seller information names Lux Global Inc, 1146 N Central Ave, Glendale, California, 91202.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.leadalliance.co/intelligence/zero-content-brand-affiliate-model', 'listing', 'ugc_collab', 'L.E.A.D. Alliance''s analysis of public TikTok data notes the @topluxnutrition account carries ~117,500 followers with zero posts of its own, and its bio exists to route creators into an affiliate relationship (''Creator? Email us for collabs'') — the brand owns its category entirely through other people''s content.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 28, 20, 13, 4, 10, 4, '{"niche_fit": "Pure-play supplements in TikTok''s strongest wellness niche (magnesium/sleep/stress), with low price points built for creator video conversion.", "ugc_evidence": "99.7% of revenue is affiliate-driven per TokConnect platform data, the brand account posts nothing itself, and thousands of creators actively sell its products \u2014 the strongest possible UGC evidence.", "compensation": "Platform data publishes real per-product rates (30% in Q1 2026 per FastMoss, 25% in October 2026 per TokConnect) \u2014 high rates, but they vary by product and period and are not published by the brand itself, so no single rate is recorded.", "contact_access": "No public email or application page could be verified; the only creator route is the TikTok bio''s ''email us for collabs'' line and TikTok Shop itself.", "opportunity_availability": "TikTok Shop affiliate products are open to creators without a separate brand application.", "credibility": "US-registered seller (Lux Global Inc, Glendale CA) with 4.1M TikTok Shop units sold and a 4.5-rated official shop, though the brand is young and sells mainly through social commerce."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('NeoCell', 'https://www.neocell.com', 'Collagen specialist founded in 1998 (''Collagen Experts Since 1998'') selling collagen peptide powders, tablets and liquids plus hyaluronic acid, biotin and joint formulas, manufactured in the United States. Its Collagen Peptides Powder was the #4 best-selling product on TikTok Shop US in Q1 2026 with $8.3M in quarterly revenue.', 'United States', 'published') returning id into bid;
