  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.neocell.com/pages/frequently-asked-questions', 'official_site', 'general', 'NeoCell''s own FAQ describes nearly 30 years as a collagen leader, products manufactured in the United States, and gives customerservice@neocell.com as the company email; its product pages claim the #1 beauty supplement brand position (SPINS data).', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.fastmoss.com/blog/top-selling-products-tiktok-shop-us-q1-2026/', 'listing', 'affiliate', 'FastMoss''s Q1 2026 TikTok Shop US top-10 ranks NeoCell Collagen Peptides Powder 20oz #4 with $8,303,193 Q1 revenue, 265,765 orders, 516,867 peak units sold and a 23% commission.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://loriballen.com/the-collagen-powder-thats-printing-money-on-tiktok-shop/', 'listing', 'compensation', 'A TikTok Shop earnings roundup reports NeoCell Collagen Bio-Peptides paying up to 26% commission and ~$2.7M in 30-day revenue, while an older affiliate directory (AffJumbo) quotes 6% with a 30-day cookie for a legacy NeoCell program — the figures conflict across sources and periods, so no single commission rate is recorded.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 16, 12, 6, 9, 5, '{"niche_fit": "Collagen sits at the intersection of supplements and beauty-from-within \u2014 two of TikTok''s strongest content categories \u2014 with an easy routine-demo format.", "ugc_evidence": "A top-5 TikTok Shop product sustained across all three months of Q1 2026 on creator routine and before/after content, though the brand publishes no formal creator program page.", "compensation": "Platform data publishes a 23% TikTok Shop rate for the hero product, but other reports say up to 26% and a legacy listing says 6%, so the rate is recorded as unpublished/conflicting rather than a single figure.", "contact_access": "Only a general customer service email is published on the brand''s own site; no creator or partnerships contact could be verified.", "opportunity_availability": "TikTok Shop affiliate products are open to creators without a separate brand application.", "credibility": "Founded 1998, US-manufactured, distributed in 20+ countries with national retail presence and category-leader claims backed by SPINS data."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('GuruNanda', 'https://gurunanda.com', 'Buena Park, California wellness brand (GuruNanda LLC, founded 2015) built on Ayurvedic-inspired oral care — oil pulling, toothpaste, water flossers — plus essential oils and diffusers. Its influencer team runs one of TikTok Shop''s largest affiliate engines: 85,000+ affiliate creators and $93M+ in lifetime GMV across 152 active products.', 'United States', 'published') returning id into bid;
