  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'GuruNanda Affiliate Program (Partner Program)', 'https://gurunanda.com/pages/partner-program', 'https://gurunanda.com/pages/partner-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://gurunanda.com/pages/partner-program', 'official_site', 'affiliate', 'GuruNanda''s own Partner Program page runs its Affiliate Program: earn 10% on every order referred, 30-day cookie window, monthly payouts, your audience gets 10% off, and most affiliates are approved within 24 hours with instant dashboard access.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.linkedin.com/company/gurunandallc', 'listing', 'ugc_collab', 'A GuruNanda LLC LinkedIn post for YFCon 2026 describes its Director of Influencer Marketing running an affiliate network of 85,000+ creators driving $93M+ in lifetime GMV and 8M+ units sold across just 152 active products, with a 4.8-star TikTok shop rating.', 'publicly_reported', now());
