  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 20, 12, 10, 9, 5, '{"niche_fit": "Oral care and natural wellness rituals are proven TikTok content categories, and the brand''s oil-pulling products are built for demo videos.", "ugc_evidence": "85,000+ affiliate creators, $93M+ lifetime GMV and a dedicated influencer marketing team \u2014 a maximal, quantified creator engine.", "compensation": "The brand''s own page publishes 10% on every order with monthly payouts plus a 10% audience discount; an older 7.5% network listing is superseded by the brand''s own terms.", "contact_access": "A public program page with an application form on the brand''s own site; no direct email is published, keeping this mid-band.", "opportunity_availability": "Open application on the official site with most affiliates approved within 24 hours.", "credibility": "Established 2015 company (51-200 employees) with national retail distribution and a 4.8-star TikTok shop."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('M3 Naturals', 'https://m3naturals.com', 'Florida-based beauty and body-care brand (M3 Naturals Ventures LLC) known for anti-cellulite massage oils, body scrubs, foot soaks and lymphatic drainage tools, made in the USA and also sold at Ulta Beauty. Its TikTok Shop official store has sold 677K+ units, with hero products carrying dense rows of commission-earning creator videos.', 'United States', 'published') returning id into bid;
