  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://rootlabshealth.com/products/root-labs-liposomal-magnesium-ashwagandha-gummies-with-beadlet-technology-control', 'official_site', 'general', 'Root Labs'' official product pages detail its gummy line (10-form liposomal magnesium with KSM-66 ashwagandha, sea moss, shilajit Alpha), third-party testing with transparent COAs, and US-only shipping; the brand''s own support knowledge base publishes support@rootlabshealth.com.', 'publicly_reported', now());
