  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 16, 5, 7, 9, 4, '{"niche_fit": "Shilajit, sea moss and magnesium gummies sit squarely in TikTok''s highest-velocity supplement niches.", "ugc_evidence": "6,341 active creators and ~26,000 linked videos on a single SKU in 30 days is strong, quantified creator adoption.", "compensation": "No commission rate is published in any fetched source, so this stays at the no-data band.", "contact_access": "A support email is published in the brand''s own help knowledge base, but there is no creator or partnerships contact.", "opportunity_availability": "TikTok Shop affiliate products are open to creators without a separate brand application.", "credibility": "US company with 1.8M TikTok Shop units sold and published third-party testing, tempered by some fulfillment complaints visible in product reviews."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Hillside Shilajit', 'https://hillsideshilajit.com', 'Family-owned shilajit brand founded in 2018 selling 60-day sun-dried Himalayan shilajit resin, honey sticks, gummies and capsules worldwide (Halal certified, lab tested). It became Malaysia''s #1 shilajit brand within 12 months by building a TikTok affiliate community of 145,000+ creators that contributes 86% of its total GMV, per TikTok''s own published case study.', 'Malaysia', 'published') returning id into bid;
