  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ads.tiktok.com/business/en/inspiration/hillside-shilajit-case-study', 'listing', 'affiliate', 'TikTok for Business''s published case study: Hillside Shilajit built a community of over 145,000 affiliates within 12 months, affiliates contributed 86% of total GMV, and Q4 2025 order volume rose 227% with 3.56x average ROI using Affiliate Creatives for Ads and Product GMV Max.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://hillsideshilajit.com', 'official_site', 'general', 'Hillside Shilajit''s official site describes a family-owned brand founded in 2018, a 60-day sun-dried purification process, Halal certification and global shipping, and publishes Info@hillsideshilajit.com plus regional phone numbers; its wholesale page publishes reseller@hillsideshilajit.com for sellers and distributors.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.threads.com/@nihabkhan1/post/DfT6WTSEZGo', 'listing', 'ugc_collab', 'Founder Nihab Khan''s Threads posts, citing the TikTok-published case study, state affiliates generated 86% of total GMV through a network of over 145,000 affiliates built within 12 months, corroborated by his own Malaysia partner dashboard showing 84.1% affiliate GMV share.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 19, 5, 9, 9, 4, '{"niche_fit": "A single-hero-ingredient wellness brand in TikTok''s proven shilajit niche; narrower than multi-line supplement brands but perfectly matched to the platform.", "ugc_evidence": "TikTok''s own case study documents 145,000+ affiliates driving 86% of GMV \u2014 exceptional, platform-verified creator evidence.", "compensation": "The case study calls commissions ''competitive'' but no rate is published in any fetched source, so this stays at the no-data band.", "contact_access": "Two published emails on the brand''s own site, including a reseller/partnerships address that invites online sellers to send their TikTok profiles.", "opportunity_availability": "TikTok Shop affiliate products are open to creators; the brand actively recruits sellers through its wholesale page.", "credibility": "Operating since 2018 with a TikTok-published success case study and Halal/GMP certifications; its home market is Malaysia rather than the US."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Neurogum', 'https://neurogum.com', 'Functional gum and mints brand (Neuro) packing 40mg of natural caffeine plus L-theanine and B-vitamins into every piece for energy, focus and calm — zero sugar, vegan, with 10M+ pieces sold through its site and national retail. It runs an affiliate program through CJ and a tiered TikTok Shop creator ladder (levels L1-L7) with a Discord creator community, where a top creator reportedly earned ~$150,000 in one month.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'wellness'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'CJ Affiliate', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.affiliate-toolkit.com/program/neurogum/.', null, 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'NeuroGum affiliate program (via CJ Affiliate)', null, 'https://www.affiliate-toolkit.com/program/neurogum/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.affiliate-toolkit.com/program/neurogum/', 'affiliate_network', 'affiliate', 'Affiliate-toolkit''s NeuroGum page, quoting the brand''s own affiliate page, states a 3% default sales commission, 30-day cookie and in-house affiliate management with bonuses and customized offers for top partners, and instructs publishers to apply for NeuroGum at CJ.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/neurogum/', 'affiliate_network', 'affiliate', 'Lasso''s NeuroGum program page lists 3% per sale with a 30-day cookie, and its join button routes to CJ''s signup (signup.cj.com).', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.flexoffers.com/affiliate-programs/neurogum-affiliate-program/', 'affiliate_network', 'compensation', 'FlexOffers lists the NeuroGum program at a 2.4% payout with a 30-day cookie (updated February 2025) — conflicting with the 3% on the brand''s own affiliate page and Lasso, so no single rate is recorded.', 'needs_review', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://briefread.com/en-GB/summary/how-brands-turn-small-influencers-into', 'listing', 'ugc_collab', 'A summary of founder Kent Yoshimura''s interviews describes NeuroGum''s creator system: samples and a Discord community for creators, tiered commissions unlocking higher rates and retainers at sales thresholds, and a top creator making around $150,000 in a single month.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://neurogum.com/products/energy-caffeine-gum?variant=12397826211930&view=lp2', 'official_site', 'general', 'Neuro''s official store sells Energy & Focus gum and mints at $24.99 with 40mg natural caffeine and L-theanine per piece, zero sugar and vegan; the brand text quoted by affiliate-toolkit claims over 10 million pieces sold.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 15, 6, 5, 8, 5, '{"niche_fit": "A novel functional format (caffeinated gum/mints) with strong productivity and study/work content angles for creators.", "ugc_evidence": "A documented tiered creator ladder with a Discord community, sampling and reported six-figure top-creator months, though the web affiliate program itself is small.", "compensation": "The web program''s headline rate is low and conflicting (3% brand page/Lasso vs 2.4% FlexOffers), while the better-paying TikTok tier rates are not published \u2014 recorded as no verified rate.", "contact_access": "Application runs through CJ; the brand page''s contact email could not be cleanly verified from fetched text, so no contact is recorded.", "opportunity_availability": "Open publisher application via CJ Affiliate.", "credibility": "10M+ pieces sold, national retail distribution and repeat national media/Shark Tank exposure."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Rythm Health', 'https://rythmhealth.com', 'At-home blood testing subscription founded in 2024 — a painless monthly self-collection kit (under 5 minutes, courier pickup) measuring 25+ biomarkers across hormones, heart health and metabolic fitness for $79/month, with personalized results in its app. Inc. reports $157M in total financing and celebrity users including Diplo and Sara Blakely; the company recruits creators through an open affiliate program on Dub and also appears among Trybe''s brand programs.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'health'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'creator_application', null, 'https://partners.dub.co/rythmhealth/apply', 'https://partners.dub.co/rythmhealth', 'needs_review', null);
