  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Rythm Health Affiliate Program (Dub)', 'https://partners.dub.co/rythmhealth/apply', 'https://partners.dub.co/rythmhealth', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://partners.dub.co/rythmhealth', 'official_site', 'affiliate', 'Rythm Health''s own affiliate program page (hosted on Dub) offers 10% cash commission on every new customer your content converts, paid weekly, plus a $50 commission on first use of your unique discount code and a free monthly blood testing subscription worth $1,200/year; affiliates must create at least two ad-ready short-form videos per month and attend weekly coaching calls, and all applications are approved by the Rythm team.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.inc.com/rachel-suleymanov/at-home-blood-testing-startups-celebrity-backers-theranos/91435303?utm_campaign=freeform&utm_source=linkedin&utm_medium=social&trk=organization_guest_main-feed-card', 'listing', 'general', 'Inc.''s profile of the at-home testing boom reports Rythm Health was founded in 2024, has secured $157M in total financing, charges $79/month for testing of 25+ biomarkers, and confirms its affiliate program pays a 10% cash commission with some affiliates earning $5,000-$50,000 per month.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.seoaffiliatedomination.com/blog/trybe', 'listing', 'ugc_collab', 'A fetched guide to Trybe''s creator platform lists Rythm Health among the brands with live Trybe programs, and Rythm''s own 2026 job posts (TikTok Shop Lead; Creator Partnerships Specialist) describe a performance-driven UGC creator program it is actively staffing.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 16, 14, 11, 7, 5, '{"niche_fit": "A health-data service rather than a classic shoppable product, but squarely in the wellness-creator niche with strong before/after biomarker content angles.", "ugc_evidence": "A structured, staffed creator program (dedicated partnerships hires, weekly coaching, content briefs) plus a Trybe program listing \u2014 real infrastructure, though younger than the product brands here.", "compensation": "Published on the brand''s own program page: 10% cash commission paid weekly, a $50 flat bounty on first discount-code use, and a free $1,200/year testing subscription \u2014 the richest verified terms in this group.", "contact_access": "A public application form on the program page collecting social profiles and content plans.", "opportunity_availability": "Open application, but approval is selective and the program requires two ad-ready videos per month plus weekly calls.", "credibility": "$157M raised since 2024 per Inc., national press coverage and named celebrity users."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Micro Ingredients', 'https://www.microingredients.com', 'Bulk supplements and superfoods brand (DPL Trading Inc) selling 270+ SKUs — collagen peptides, mushroom powders, vitamins, electrolytes and organic herb powders — through its own site, Amazon and a top-10 TikTok Shop US store. FastMoss put its Q1 2026 TikTok revenue at $26.1M with a 4.8 shop rating, powered by roughly 67,000 affiliated creators on an open, no-application affiliate model.', 'United States', 'published') returning id into bid;
