  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.fastmoss.com/blog/tiktok-shop-profitability-q1-2026-top-10-us-sellers/', 'listing', 'affiliate', 'FastMoss''s Q1 2026 Top 10 US TikTok Shops analysis ranks Micro Ingredients #9 (Health, DPL Trading Inc, 4.8 shop rating) with $26.1M revenue, 811,700 units, 270 active products and 67,000 affiliated creators, noting health/supplement shops typically pay 20-30% creator commissions.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://shop.tiktok.com/us/pdp/micro-ingredients-hair-thickening-supplement-bundle/1731721010660938413', 'official_site', 'ugc_collab', 'Micro Ingredients'' TikTok Shop product pages show an OFFICIAL SHOP with 7.4M units sold and repeated ''Creator earns commission'' video rows; October 2026 case-study posts citing FastMoss data describe a flat 15% open commission on every SKU with no application or sample gatekeeping, and 389,200 shoppable videos.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/micro-ingredients/', 'affiliate_network', 'compensation', 'Lasso lists Micro Ingredients at ''up to 15.0%'' with a 14-day cookie via its marketplace — a ceiling figure consistent with the reported flat 15% TikTok Shop rate, but not a brand-published rate, so commission_rate is recorded as null.', 'needs_review', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://microingredients.com/collections/vitamins', 'official_site', 'general', 'Micro Ingredients'' official store catalogs hundreds of supplement and superfood SKUs across vitamins, energy/performance, cognition and immune support collections.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 19, 10, 3, 10, 5, '{"niche_fit": "A 270-SKU supplement catalog means every wellness creator can find a matching product; simple powder-demo content is the platform''s proven format.", "ugc_evidence": "67,000 affiliated creators, ~389,000 shoppable videos and an explicitly open, faceless-friendly affiliate model documented in FastMoss-cited case studies.", "compensation": "A flat 15% open commission is consistently reported from platform data, but the brand does not publish the rate itself, so it is documented rather than recorded.", "contact_access": "No public creator or general contact could be verified from fetched pages.", "opportunity_availability": "Open TikTok Shop affiliate access with no application or sample gatekeeping reported \u2014 maximal availability.", "credibility": "Top-10 TikTok Shop US seller with a 4.8 shop rating, 7.4M units sold and a large established DTC catalog."}'::jsonb);
