  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://rateful.ai/brand/seese-x', 'listing', 'affiliate', 'Rateful''s TikTok Shop data for the SEESE X store (Tools & Hardware) estimates ~96% of its sales in the 30 days to Nov 3, 2026 came through affiliate creators; creators with TikTok Shop affiliate access can add the products to their showcase and earn commission on every sale.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://deviantly.ai/blog/who-is-the-top-earner-on-tiktok-shop-88921', 'listing', 'ugc_collab', 'Deviantly''s TikTok Shop telemetry (data as of Nov 2, 2026) puts the SEESE Cordless Pressure Washer Gun at $2,273,223 in 30-day GMV with 3,332 creators promoting it - a large, crowded creator pool, so saturation is recorded as high.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 18, 8, 3, 9, 4, '{"compensation": "No public commission rate or cap statement exists; TikTok Shop rates are set per product inside the platform, so this stays low-mid.", "contact_access": "No public creator contact, email or application page was found; the only route is inside TikTok Shop.", "credibility": "Real DTC storefront with published returns/shipping terms and a top-selling TikTok Shop product, but a young, small brand.", "niche_fit": "Cordless cleaning tools are a natural demo-driven fit for home and DIY creators on TikTok Shop.", "opportunity_availability": "Any creator with TikTok Shop affiliate access can add SEESE products to their showcase today.", "ugc_evidence": "Affiliate creators drive ~96% of the SEESE X store''s TikTok Shop sales (Rateful estimate), and the hero pressure washer drew 3,332 creators in 30 days (Deviantly)."}'::jsonb);
