  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 14, 8, 3, 9, 3, '{"compensation": "TikTok Shop pays per sale, but rates are per-product and unpublished, so this stays mid-low.", "contact_access": "No public creator email was found; routes are TikTok Shop and direct sponsorship outreach.", "credibility": "A real LLC with its own store and 1.1M+ TikTok Shop units sold, but BBB reviews flag fulfilment and refund complaints.", "niche_fit": "Middle Eastern fragrance is a proven TikTok beauty niche and the catalog is priced for impulse buys (~$41 average).", "opportunity_availability": "110 products are live on TikTok Shop for affiliate creators.", "ugc_evidence": "Affiliates drive ~45% of TikTok Shop sales (Rateful), and the brand sponsored 4 small beauty creators in the last 30 days."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Full Circle Home', 'https://fullcirclehome.com', 'Certified B Corporation making sustainable cleaning tools and home goods (Bubble Up brushes, cutting boards, composting, Soma water filtration) from bamboo, recycled plastic and organic cotton; runs a cash-commission affiliate program for creators, distinct from its store-credit refer-a-friend scheme.', 'United States', 'published') returning id into bid;
