  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 11, 10, 5, 9, 5, '{"compensation": "Cash commissions via PayPal are documented, but published rates conflict (5-10% vs 15%), keeping this mid-range.", "contact_access": "Program pages exist on multiple networks; no public partnerships email was verified.", "credibility": "Certified B Corporation with Wirecutter-cited products and national retail presence.", "niche_fit": "Sustainable home and zero-waste cleaning is a dedicated creator niche, and the products are display-worthy by design.", "opportunity_availability": "Open affiliate program on UpPromote with additional ShareASale and FlexOffers listings.", "ugc_evidence": "The program is explicitly built for creators, bloggers and influencers in sustainability and home niches, with creative assets provided."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Ironway', 'https://ironway.com', 'Direct-to-consumer watch brand selling the Field Watch 41, a rugged analog field watch (sapphire crystal, Japanese quartz movement, NATO straps) aimed at outdoor, hunting, fishing and veteran audiences, marketed almost entirely through creator videos run as paid ads.', 'United States', 'published') returning id into bid;
