  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Brand direct', 15, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://ironway.com/de/pages/creator-program.', 'https://ironway.com/de/pages/creator-program', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Ironway Creator Commission Program', 'https://ironway.com/de/pages/creator-program', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ironway.com/de/pages/creator-program', 'official_site', 'affiliate', 'Ironway''s own Creator Commission Program page (fetched): creators join via Trybe, receive a free Field Watch 41 to keep, and earn 15% of every sale their video generates when Ironway runs it as a paid ad; tracking is Trybe server-side with a 7-day last-click model and payouts are automatic weekly (commission lands within 7 days). The brand says it spends six figures a month on ads and scales spend on videos reaching 1.5x ROAS or higher.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ironway.com/de/pages/creator-program', 'official_site', 'compensation', 'Cap verdict — UNCAPPED, in the program''s own words on its own page: ''you earn 15% of every sale it generates. No flat fees. No limits.''; ''Most creator programs cap your upside at a flat fee. Ours doesn''t.''; and a section headed ''Unlimited upside tied to ad spend''. This is an explicit no-earnings-limit statement in the brand''s own program terms, so commission_cap is recorded as uncapped.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.instagram.com/p/DdolttzILNz/', 'listing', 'general', 'Ironway''s official Instagram account @ironway (about 15K followers) posts Field Watch 41 product content aimed at outdoor and military-style users, matching the creator demographic its program page says it recruits (men 40+, hunters, fishermen, veterans).', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 18, 18, 10, 9, 3, '{"niche_fit": "A single hero product (field watch) built for outdoor/men''s lifestyle creators \u2014 a focused but real fashion-accessory niche fit.", "ugc_evidence": "The entire business model is creator video: the brand''s own page describes scaling creator content with six-figure monthly ad spend, partnership ads from creators'' own accounts, and an active creator community with weekly briefs.", "compensation": "Published 15% of generated sales with an explicit no-limit statement on the brand''s own program page and weekly automatic payouts \u2014 top-band published terms.", "contact_access": "A public program page with a direct Trybe application route, but no published email or partnerships contact.", "opportunity_availability": "Open application via Trybe with no minimum following; the brand reviews profiles and ships the product free.", "credibility": "Young, small DTC brand (about 15K Instagram followers); its six-figure ad-spend claims are self-reported and unverified."}'::jsonb);
