  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Nello Creator Program (via Trybe)', 'https://drinknello.com/pages/trybe-terms-conditions', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://drinknello.com/pages/trybe-terms-conditions', 'official_site', 'affiliate', 'Nello''s own published Creator Program Terms & Conditions (fetched): creators earn 3% of qualifying Meta ad spend attributable to their submitted content while Nello runs it as paid ads on Meta placements; payouts monthly within 30 days via Trybe (PayPal, ACH or Stripe) with a $25 minimum; participants must be 18+ with an active Trybe account and submit raw, un-watermarked 1080p+ footage.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://drinknello.com/pages/trybe-terms-conditions', 'official_site', 'compensation', 'The terms state no earnings cap, but they also state Nello makes no guarantees about the volume of ad spend or how long content runs — there is no explicit no-cap statement, so commission_cap is honestly recorded as unknown under the strict filter.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://drinknello.com', 'official_site', 'general', 'Nello''s homepage (fetched) sells its Superpowder drink mixes (Supercalm with KSM-66 ashwagandha and L-theanine, Superfocus, Superbalance, Superglow, Supersleep) and states ''Find us on Instagram and TikTok @drinknello''.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 16, 8, 9, 8, 4, '{"niche_fit": "Calm/focus/sleep drink powders are a core wellness-creator niche with highly demonstrable products.", "ugc_evidence": "A formal, documented creator program with full published terms, content briefs and raw-footage submission rules on the brand''s own site.", "compensation": "Published pay exists (3%) but it is a share of ad spend rather than sales, and the brand guarantees no spend volume or duration, so real earnings are uncertain.", "contact_access": "Full program terms published on the brand''s own site with a program contact route on the same page.", "opportunity_availability": "Open to any 18+ creator with a Trybe account; a VIP tier is invite-only but the base program is an open route.", "credibility": "Established DTC wellness brand selling multiple formulated products with GMP-certified, third-party-tested claims on its own site."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Shark', 'https://www.sharkninja.com', 'Shark is the home-appliance brand of SharkNinja (vacuums, air fryers, blenders, beauty devices and cleaning products), sold through sharkninja.com and major retailers; its consumer creator program is called SharkNinja Storytellers.', 'United States', 'published') returning id into bid;
