  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'SharkNinja Storytellers', 'https://www.sharkninja.com/discover/community/storytellers', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.sharkninja.com/discover/community/storytellers', 'official_site', 'affiliate', 'SharkNinja''s official Storytellers page (fetched): the brand''s own free creator program pays commission on orders from the creator''s storefront — ''8% rising to 10%'' (commissions start at 8% and grow to 10%); open to US residents with at least 1,000 total followers who posted in the last 30 days; commission paid monthly after each order''s return period closes; creators tag @SharkNinja and use #SharkStorytellers.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.glossy.co/pop/sharkninja-fans-beauty-creators-holiday-shopping/', 'industry_press', 'ugc_collab', 'Glossy reported SharkNinja''s October 2026 launch of Storytellers: everyday creator tier at 8-10% commission, a professional tier at 8-12%, and an invitation-only VIP tier at 12-15%; the company also sells through TikTok Shop affiliates.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 19, 12, 12, 9, 5, '{"niche_fit": "Home appliances and cleaning/beauty devices are among the highest-volume review and demo niches for creators.", "ugc_evidence": "A structured, brand-run creator program (Storytellers) built around everyday creators'' unboxings, how-tos and reviews, launched publicly in October 2026 with tiered commissions.", "compensation": "Published commission on the brand''s own page: 8% starting, rising to 10%, paid monthly \u2014 clear, current terms.", "contact_access": "A public program page on the brand''s own domain with a direct join route and a full FAQ.", "opportunity_availability": "Free and openly joinable for US creators with 1,000+ followers; higher tiers exist for professionals and invited VIPs.", "credibility": "SharkNinja is a large, established public-company appliance maker with nationwide retail distribution."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Sally Beauty', 'https://www.sallybeauty.com', 'The world''s largest retailer of professional beauty supplies, operating more than 2,700 Sally Beauty stores and selling 8,000+ professional hair color, hair care, nail and beauty products to consumers and salon professionals.', 'United States', 'published') returning id into bid;
