  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Sally Beauty Affiliate Program (CJ Affiliate)', null, null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.affiliate-toolkit.com/program/sally-beauty/', 'affiliate_network', 'affiliate', 'Affiliate-toolkit''s program page (fetched) confirms Sally Beauty''s affiliate program runs on CJ Affiliate (''Apply for Sally Beauty at CJ'') and quotes the program''s own text: ''earn up to 15% commission'', 15-day cookie duration and a daily-updated product feed; the same page describes Sally Beauty as the world''s largest retailer of professional beauty supplies with more than 2,700 stores and over 8,000 products.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://carlbroadbent.com/affiliate-program/affiliate-programs-for-beauty-products/', 'listing', 'compensation', 'Rate conflict, so commission_rate is null: several directories state 15% on CJ with a 15-day cookie, but others state 5% on full-price purchases and 2% on coupon-code purchases via CJ, and another lists 10%. ''Up to 15%'' is a ceiling, not a settled rate, and the sources conflict, so no single rate is recorded.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 10, 8, 8, 8, 5, '{"niche_fit": "Professional hair color, hair care and nails are core beauty-creator categories, and Sally is the category''s biggest retailer.", "ugc_evidence": "A long-running publisher affiliate program exists, but no formal creator/UGC program with briefs or community was found \u2014 evidence is affiliate-style rather than creator-style.", "compensation": "A published ceiling (''up to 15%'') exists, but directory rates conflict (15% vs 5%/2% vs 10%), so compensation is scored on the conflicted evidence, not a settled rate.", "contact_access": "Application route is through CJ Affiliate and the program maintains an affiliate team on that network; no direct public creator contact was published.", "opportunity_availability": "Open application through CJ Affiliate for publishers and creators.", "credibility": "Sally Beauty Holdings is a long-established public retailer (since 1964) with thousands of stores internationally."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Harry''s', 'https://www.harrys.com', 'Men''s grooming company founded in New York in 2013 selling razors and German-engineered blades on subscription, plus shave gel, skincare, body wash and deodorant, through harrys.com and major retailers; it reports more than 20 million customers.', 'United States', 'published') returning id into bid;
