  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Harry''s Affiliate Program', null, null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://affi.io/m/harrys', 'affiliate_network', 'affiliate', 'Harry''s own affiliate program text, mirrored on affi.io (fetched): ''The Harry''s affiliate program is offering £4 per Trial Set subscription sign-up and 5% on any one-off purchases'', with a 30-day cookie, banners/creatives and voucher codes for approved affiliates. The £4 is a flat per-sign-up bounty; the 5% is the recorded percentage rate. The same page states Harry''s was created in 2013 by founders Jeff and Andy and has been tried by over 20 million customers.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/harrys-2/', 'listing', 'compensation', 'Other directories quote different figures — Lasso lists ''up to 15%'' (a rate ceiling, not a rate) and Shopper lists 5.6% — so the brand''s own program text (5% on purchases plus £4 flat per Trial Set sign-up) is used as the basis and the alternatives are documented here rather than blended.', 'needs_review', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://quilted-bull-fd2.notion.site/Harry-s-New-Affiliate-Onboarding-1f3d3b1a05c0805c9cc4c4c98ce6ed92', 'listing', 'ugc_collab', 'A public Harry''s affiliate onboarding guide includes pro tips for making high-performing TikTok content and a section on TikTok-exclusive bundles, showing the program actively recruits and coaches short-form video creators.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 11, 10, 7, 8, 5, '{"niche_fit": "Men''s grooming and shaving is a well-defined creator niche and Harry''s is one of its best-known DTC brands.", "ugc_evidence": "An established affiliate program plus a public onboarding guide with TikTok content coaching and TikTok-exclusive bundles show active creator recruitment, though it is affiliate-led rather than a UGC community.", "compensation": "Published terms from the brand''s own program text: 5% on purchases plus a flat \u00a34 per subscription sign-up, 30-day cookie.", "contact_access": "Joining is via the program''s network listing; no public partnerships email was found on the fetched pages.", "opportunity_availability": "Open application with approval; creatives and voucher codes provided once approved.", "credibility": "Founded 2013, 20M+ customers, own German blade factory and national retail distribution \u2014 fully established brand."}'::jsonb);
