  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.shopper.com/partnerships/byltbasics-com-affiliate-program', 'affiliate_network', 'affiliate', 'Shopper.com''s program page (fetched) lists a Bylt Basics affiliate program paying 2% per sale with instant approval through Shopper; it publishes no cookie duration or underlying network detail, and it is the only source found, so the listing is recorded as needs_review.', 'needs_review', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.irvinecompanyretail.com/centers/newport-beach/fashion-island/bylt-basics/', 'listing', 'general', 'BYLT Basics operates its own retail stores (e.g., Fashion Island, Newport Beach, CA) selling premium apparel, footwear and accessories; its separate BYLT+ customer rewards program pays store credit and was NOT used as the qualifying route (store-credit schemes are excluded) — inclusion rests on the Shopper-listed affiliate program.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 8, 5, 5, 6, 4, '{"niche_fit": "Premium men''s basics and athleisure are a strong, content-friendly fashion niche with a loyal DTC following.", "ugc_evidence": "No formal creator or ambassador program could be verified on the brand''s own site; evidence is a single third-party affiliate listing.", "compensation": "Only one source publishes a rate (2% per sale) and it is low and unverified against the brand''s own pages, so compensation stays low.", "contact_access": "No public creator application page or partnerships contact was found on the brand''s own site; the only route is the Shopper listing.", "opportunity_availability": "Shopper advertises instant approval, but with a single unverified listing the real availability is uncertain.", "credibility": "Established DTC apparel brand with physical retail stores and national e-commerce presence."}'::jsonb);
