  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 17, 6, 6, 7, 5, '{"niche_fit": "Mainstream fashion (including the pyjama/seasonal ranges TikTok documents selling out) is a core creator category, and Tu is a top-10 UK clothing retailer.", "ugc_evidence": "TikTok''s own case study documents Tu running its affiliate program at scale \u2014 30 launch creators growing to over 200 producing branded content with a 92% sell-through.", "compensation": "No commission rate is published anywhere fetched; TikTok Shop rates are per-product and only visible inside the platform, so compensation scores low on evidence.", "contact_access": "The route is inside TikTok Shop''s affiliate system; no public creator contact or application page was found on the brand''s own site.", "opportunity_availability": "TikTok Shop affiliate activation is documented and the brand demonstrably onboards creators, though UK creators need TikTok Shop affiliate access.", "credibility": "Tu is Sainsbury''s clothing brand \u2014 one of the UK''s largest retailers \u2014 with around 400 in-store locations."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('The Motion Books', 'https://themotionbooks.com', 'Maker of video books — premium physical books with a built-in screen that play your own videos — sold as wedding, memorial and family gifts through themotionbooks.com, Amazon and Etsy, and heavily promoted through TikTok Shop and affiliate creators.', 'United States', 'published') returning id into bid;
