  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'The Motion Books Affiliate Program', 'https://themotionbooks.com/affiliate-program/', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://themotionbooks.com/affiliate-program/', 'official_site', 'affiliate', 'The Motion Books'' own affiliate program page (fetched): ''Join our affiliate program and earn 15% on every purchase you refer!'' — affiliates get a dashboard, custom tracking links and monthly payouts via PayPal; the page''s Q&A repeats ''You will earn 15% of each sale that is made using your referral link'' and cites a 13% conversion rate for affiliate traffic.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://themotionbooks.com/faq-business-partnership/', 'official_site', 'compensation', 'Rate conflict on the brand''s own site, so commission_rate is null: the affiliate program page states 15%, but the brand''s business-partnership FAQ states ''You will earn 5% of each sale that is made using your referral link'' for its affiliate partnership. Both are the brand''s own words describing referral-link earnings, so no single rate is recorded.', 'needs_review', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://themotionbooks.com/affiliate-program/', 'official_site', 'ugc_collab', 'The brand''s affiliate page showcases named working affiliates (wedding/event creators with their follower counts) and states the brand has over 48K Instagram followers, 145K+ TikTok followers and 20M+ social video views; TikTok''s own case study for the brand (cited in the lead research) credits affiliate creators with a 13,111% increase in affiliate GMV.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 20, 14, 7, 9, 9, 3, '{"niche_fit": "A single viral gift product (video books for weddings and family moments) \u2014 narrower than a full lifestyle range but very demonstrable on video.", "ugc_evidence": "The brand runs its own affiliate program, showcases working creator affiliates on the program page, and TikTok credits affiliate creators with outsized GMV growth for the brand.", "compensation": "Pay terms are published on the brand''s own site but conflict (15% vs 5%), so compensation is scored down and the rate is left null.", "contact_access": "A public affiliate page with sign-up and dashboard on the brand''s own domain.", "opportunity_availability": "Open self-serve sign-up on the brand''s own affiliate page.", "credibility": "Small independent brand (The Motion Books LLC) with strong marketplace ratings (4.5 stars on Amazon, 4.9 on Etsy) but limited scale."}'::jsonb);
