  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 18, 16, 5, 5, 6, 3, '{"niche_fit": "Novelty sour candy is a fun but narrow food niche; reaction/taste-test content fits TikTok well.", "ugc_evidence": "TikTok''s own case study documents an explicitly affiliate-led TikTok Shop strategy with affiliate content at the center of the brand''s growth.", "compensation": "No commission rate is published anywhere fetched \u2014 TikTok Shop rates are per-product and in-app only.", "contact_access": "Affiliate relationships are agency-managed per TikTok; no public application page or creator contact was found on the brand''s own site.", "opportunity_availability": "Products are sellable through TikTok Shop''s open affiliate system in the UK, but there is no brand-run open application.", "credibility": "Brand launched in 2011 with wide international retail distribution (25,000+ stores), though it is a mid-size confectionery company."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('LoomLab Outfitters', null, 'TikTok Shop apparel seller (operated by OIUHUYYTG LLC of Colorado Springs, Colorado) selling graphic tees, hoodies and work footwear; its ''America''s Favored'' beach graphic tee was one of TikTok Shop US''s best-selling products of Q2 2026. No standalone website was found — the storefront is TikTok Shop only.', 'United States', 'published') returning id into bid;
