  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 15, 11, 4, 7, 2, '{"niche_fit": "Graphic tees and hoodies are proven outfit-content products, and this shop owns a top-5 TikTok Shop apparel product.", "ugc_evidence": "Third-party TikTok Shop analytics attribute about 54% of the shop''s sales to affiliates, and its flagship product''s rise was affiliate-content driven.", "compensation": "A 10% commission is published for its flagship product by FastMoss''s TikTok Shop data; per-product rates may vary across the catalogue.", "contact_access": "No website, email or public contact exists for the shop \u2014 TikTok Shop is the only route.", "opportunity_availability": "Its products are open inside TikTok Shop''s affiliate system to creators with affiliate access.", "credibility": "An anonymous-LLC TikTok Shop seller with no standalone brand presence, website or verifiable company history."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Samsung', 'https://www.samsung.com', 'South Korean consumer electronics giant selling smartphones, TVs, home appliances and accessories through Samsung.com. It runs open affiliate programs an individual creator can actually join: a US program for Samsung.com/US listed on FlexOffers (apply online, free, 14-day cookie), and Samsung''s own affiliate program pages (e.g. Samsung Gulf) that route sign-ups through the Optimise network and state that anyone - individual or company - can join free with a website, blog or social media profile.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'technology'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'creator_application', null, 'https://www.flexoffers.com/affiliate-programs/samsung-affiliate-program/', 'https://www.flexoffers.com/affiliate-programs/samsung-affiliate-program/', 'needs_review', null);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'FlexOffers', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.flexoffers.com/affiliate-programs/samsung-affiliate-program/.', 'https://www.flexoffers.com/affiliate-programs/samsung-affiliate-program/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Samsung affiliate program (FlexOffers, US) - open application', 'https://www.flexoffers.com/affiliate-programs/samsung-affiliate-program/', 'https://www.flexoffers.com/affiliate-programs/samsung-affiliate-program/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.samsung.com/ae/offer/samsung-affiliate-program/', 'official_site', 'affiliate_program', 'Samsung''s own Affiliate Program page (Samsung Gulf, fetched in full) proves an open program: ''Who can become a Samsung Affiliate Program? Anyone can join the program - whether you''re an individual or a company!'' with a valid website, blog or social media profile; sign-up is via the Optimise platform (''Sign up on Optimise... Join now''), joining is completely free, approval typically takes about 14 business days, and affiliates ''earn commission for every confirmed sale''. No percentage rate and no earnings-cap statement are published on the page, so commission_rate is null and commission_cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.flexoffers.com/affiliate-programs/samsung-affiliate-program/', 'affiliate_network', 'affiliate_program', 'FlexOffers'' Samsung affiliate program listing (fetched in full) covers Samsung.com/US: publishers join free (''Joining the Samsung Affiliate Network is simple and free... Apply now''), get affiliate links, text links and banners, track clicks/conversions/earnings in a dashboard, and the program offers a 14-day cookie duration. The listing publishes no percentage rate, so the rate stays null (third-party directories quote conflicting figures such as 1.6%/3.2%, which are not used). No creator count is published, so creator_saturation is unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 12, 8, 6, 8, 5, '{"compensation": "Commission per confirmed sale is confirmed on Samsung''s own page, but neither primary source publishes a percentage and third-party figures conflict, so the rate is recorded null.", "contact_access": "Application runs through the network pages; no public program email is published on either fetched page.", "credibility": "Samsung is a top-10 global brand and its own domain publishes the program terms fetched here.", "niche_fit": "Phones, TVs, appliances and accessories are core tech-review and unboxing creator territory, with high order values.", "opportunity_availability": "Open now: free sign-up with approval (about 14 business days on Samsung''s own route).", "ugc_evidence": "Open publisher/affiliate programs on two routes (FlexOffers US and Samsung''s own Optimise sign-up); Samsung''s own page explicitly accepts social media profiles, though the program is publisher-led rather than creator-first."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Ralph Lauren', 'https://www.ralphlauren.com', 'Iconic American luxury lifestyle brand. Scope note: Ralph Lauren''s mainline fashion affiliate program (EMEA, on Partnerize) describes itself as invite-only, so it does NOT qualify as open. The open, joinable program verified here is the Ralph Lauren Fragrances affiliate program on FlexOffers - fragrances and grooming products, a published 10% payout on online sales, a 30-day cookie, and a public Apply Now application route for individual affiliates.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'beauty'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'creator_application', null, 'https://www.flexoffers.com/affiliate-programs/ralph-lauren-fragrances-affiliate-program/', 'https://www.flexoffers.com/affiliate-programs/ralph-lauren-fragrances-affiliate-program/', 'needs_review', null);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'FlexOffers', 10, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.flexoffers.com/affiliate-programs/ralph-lauren-fragrances-affiliate-program/.', 'https://www.flexoffers.com/affiliate-programs/ralph-lauren-fragrances-affiliate-program/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Ralph Lauren Fragrances affiliate program (FlexOffers) - 10% of online sales', 'https://www.flexoffers.com/affiliate-programs/ralph-lauren-fragrances-affiliate-program/', 'https://www.flexoffers.com/affiliate-programs/ralph-lauren-fragrances-affiliate-program/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.flexoffers.com/affiliate-programs/ralph-lauren-fragrances-affiliate-program/', 'affiliate_network', 'affiliate_program', 'FlexOffers'' Ralph Lauren Fragrances Affiliate Program listing (fetched in full, page last updated September 26, 2025) states the payout verbatim: ''The payout is 10% of online sales. Gift cards are excluded.'' and a 30-day cookie duration. Its ''Joining the Program'' steps are a public application route: visit the program page, click ''Apply Now'', fill in the application form, submit and wait for approval, then receive affiliate links, banners and promotional materials, with a dedicated affiliate management team and performance incentives. No earnings-cap statement appears, so commission_cap is unknown; no creator count is published, so creator_saturation is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://affi.io/m/ralph-lauren', 'affiliate_network', 'affiliate_program', 'The mainline Ralph Lauren affiliate program (Ireland/EMEA on Partnerize, terms reproduced on this fetched listing) describes itself in the brand''s own words as ''our invite only affiliate program'' for ''best-in-class digital fashion publishers, top-tier influencers and partners'' (commission on net sales up to 8%, 30-day cookie). Because it is invite-only, the mainline fashion program does not meet this directory''s open-program rule; the entry is therefore scoped to the open Fragrances program on FlexOffers.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 20, 10, 14, 6, 7, 5, '{"compensation": "A clear, published 10% of online sales on the network listing (gift cards excluded) - the strongest published rate in this group.", "contact_access": "Public application via FlexOffers and a dedicated affiliate management team after approval; no public program email published.", "credibility": "Ralph Lauren is a globally recognised luxury brand operating since 1967, with program terms published on the network listing.", "niche_fit": "Fragrance and grooming are strong beauty/luxury creator topics; the open program is fragrances-only, not the full fashion line, which caps niche fit.", "opportunity_availability": "Fragrances program is open via Apply Now with an approval step; the mainline fashion program is invite-only, which limits overall availability.", "ugc_evidence": "The Fragrances program recruits affiliates with banners, promotional materials and launch access; the brand''s creator/influencer work on the mainline side is invite-only, so UGC evidence is moderate."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Disney', 'https://www.shopdisney.com', 'The Walt Disney Company''s official merchandise store (Disney Store / shopDisney) selling toys, apparel, collectibles and home decor across Disney, Pixar, Marvel and Star Wars. Its affiliate program is open to individual publishers and creators through FlexOffers: sign up, get approved, receive banners and text links, promote on a blog, social media or family-focused website, and earn commissions on referral purchases with a 30-day cookie.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'lifestyle'), true);
