  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'FlexOffers', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.flexoffers.com/affiliate-programs/shopdisney-affiliate-program/.', 'https://www.flexoffers.com/affiliate-programs/shopdisney-affiliate-program/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Disney Store (shopDisney) affiliate program via FlexOffers - open application', 'https://www.flexoffers.com/affiliate-programs/shopdisney-affiliate-program/', 'https://www.flexoffers.com/affiliate-programs/shopdisney-affiliate-program/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.flexoffers.com/affiliate-programs/shopdisney-affiliate-program/', 'affiliate_network', 'affiliate_program', 'FlexOffers'' Disney Store (shopDisney) affiliate program listing (fetched in full) proves an open program: ''Join the Disney Store affiliate program and earn commissions'', with a five-step public route - Sign Up (apply on the program page), Get Approved, Access Marketing Assets (banners, text links, promotional creatives), Promote Products on a blog, social media or family-focused website, Earn Commissions - and a stated 30-day cookie duration. The page explicitly calls the program ''perfect for content creators, influencers, and Disney fan sites''. It publishes no percentage rate, so commission_rate is null (directories report around 2% for shopDisney, not stated on the network listing itself). No earnings-cap statement and no creator count appear, so commission_cap and creator_saturation are unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 11, 7, 6, 8, 5, '{"compensation": "Commissions on referral purchases are confirmed, but the network listing publishes no percentage (directories report roughly 2%), so the rate is recorded null and compensation scores low.", "contact_access": "Application and support run through the FlexOffers program page; no public program email is published on the listing.", "credibility": "Disney is one of the world''s most recognised entertainment brands; the program is listed by an established affiliate network.", "niche_fit": "Disney, Pixar, Marvel and Star Wars merchandise fits family, parenting, gift-guide and fan creators well; less relevant outside those audiences.", "opportunity_availability": "Open now: public sign-up with an approval step, 30-day cookie, marketing assets provided.", "ugc_evidence": "The network listing explicitly names content creators and influencers as ideal partners and supports promotion on social media, though it is a classic publisher affiliate program rather than a creator platform."}'::jsonb);
